const pedidos = [
  { id: 101, status: 'paid', total: 150 },
  { id: 102, status: 'pending', total: 80 },
  { id: 103, status: 'paid', total: 50 }
];
const pagos = pedidos.filter(p => p.status === 'paid');
const receita = pagos.reduce((soma, p) => soma + p.total, 0);
console.log(receita); // 200
